/// <summary>
///     The <c>AVAAVATOSDetails_AVAUpdateAVAEmailInvoiceToCustAccountBtn_Extension</c> class is the extension of FormControl <c>AVAInventTransferLineBundleExplode</c> in form <c>AVATOSDetails</c>
/// </summary>
[ExtensionOf(formControlStr(AVATOSDetails, AVAUpdateAVAEmailInvoiceToCustAccount))]
final class AVAAVATOSDetails_AVAUpdateAVAEmailInvoiceToCustAccountBtn_Extension
{
}

Method.Source:
/// <summary>
///    AVA <c>Clicked</c> class.
/// </summary>
public void clicked()
{
    FormDataSource          locFormDataSource;
    KCS_TOSTableCustTmp     locKCS_TOSTableCustTmp;

    FormDataSource          locKCS_TOSTableDs;
    KCS_TOSTable            locKCS_TOSTable;
    MultiSelectionHelper    locMultiSelectionHelper;

    next clicked();

    locKCS_TOSTableDs       = element.KCS_TOSTable_DS;
    locKCS_TOSTable         = locKCS_TOSTableDs.cursor();               // root KCS_TOSTable

    locFormDataSource       = element.KCS_TOSTableCustTmp_DS;
    locMultiSelectionHelper = MultiSelectionHelper::construct();
    locMultiSelectionHelper.parmDatasource(locFormDataSource);

    locKCS_TOSTableCustTmp = locMultiSelectionHelper.getFirst();

    while (locKCS_TOSTableCustTmp.RecId != 0)
    {
        //locKCS_TOSTable = locKCS_TOSTableCustTmp.avaKCS_TOSTable();   // use root KCS_TOSTable from actual datasource instead of KCS_TOSTable of corresponding TOSId in perhaps deeper level
        if(locKCS_TOSTable.RecId)
        {
            locKCS_TOSTable.updateAVAEmailInvoiceToCustAccount(locKCS_TOSTableCustTmp.CustAccount, true);
        }

        locKCS_TOSTableCustTmp = locMultiSelectionHelper.getNext();
    }
    locFormDataSource.research(true);
    locFormDataSource.refresh();
}
